function onClick(g_form) {
    var bulkNumber = g_form.getValue('number');

    var gajax = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils'); //4215
    gajax.addParam('sysparm_name', 'checkMakerType');
    gajax.addParam("sysparm_bulkid", bulkNumber);
    gajax.getXMLAnswer(response);

    function response(answer) {

        if (answer == 'true') {

            var conf = confirm("You are going to Cancel the bulk. Do you want to proceed?");

            if (conf) {
                //var url = "/x/hsb11/mss-custody-workspace/main_page/params/__state__/b64~eyJiMWM1NTU4YTFiZjU2YTEwMmFjMTIwYThiMDRiY2I3ZSI6eyJsaXN0X2NvbnRyb2xsZXIiOnsiXyI6eyJxdWVyeSI6IiJ9fX19";
                //open(url);
                //g_navigation.open('x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_filter_only=true'); //go back to Task List view
                var url = "/x/hsb11/mss-custody-workspace/list/params/list-id/10f9d3a31bb6d2d02ac120a8b04bcb96";
                top.window.location = url;

                var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils'); //call to script include "cancelItems"
                ga.addParam('sysparm_name', 'CancelMakerTask');
                ga.addParam('sysparm_bulkSysID', g_form.getUniqueValue());
                ga.getXMLAnswer(getRequiredInc);

                function getRequiredInc(response) {}

                g_aw.closeRecord();
            } else {
                location.reload(); //choose "Cancel", then refresh the bulk form, no other action
            }
        } else {
            /*
            g_navigation.open('/x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_view=bulk_tasks&sysparm_userpref_module=b758b7cb1b6e4ed46ed00e1ad34bcbb3&sysparm_query=active=true^bulk_id.numberISNOTEMPTY^GROUPBYbulk_id&sysparm_filter_only=true');
			*/
            top.window.location = "/x/hsb11/mss-custody-workspace/list/params/list-id/9de7971a1b7e9a902ac120a8b04bcb8b";

            g_aw.closeRecord();
        }

    }
}
